  public uf_syd_mxsc(as_knsj: string, as_brbm: string, ai_jslx: number, as_jylx: string, as_jydd: string, adc_ywlsh: number, as_error: string, astr_yb_mzsfqq: any): number {
    // TODO: PB body preserved as reference; behavior needs manual port.
    // // 事件: u_sybjk_his.uf_syd_mxsc()
    // //--------------------------------------------------------------------
    // // 描述:省异地业务数据明细上传
    // //--------------------------------------------------------------------
    // // 参数:
    // // 	value    	string 	as_knsj
    // // 	value    	string 	as_brbm
    // // 	value    	integer	ai_jslx
    // // 	value    	string 	as_jylx   业务类型
    // // 	value    	string 	as_jydd
    // // 	reference	decimal	adc_ywlsh	业务流水号
    // // 	reference	string 	as_error
    // //--------------------------------------------------------------------
    // // 返回:  integer
    // //--------------------------------------------------------------------
    // // 作者:	zf		日期: 2020.01.07
    // //====================================================================
    // //5	社会保障卡卡号	string	9	是
    // //6	社会保障卡卡的识别码	string	50	是
    // //7	参保地行政区划代码	string	20	否
    // //8	就医地行政区划代码	string	20	否
    // //9	医疗类别	string	3	是		参考数字字典医疗类别
    // //10	规定病种标记	string	3	否		参考蔇AT*
    // �字字典规定病种标�
    // //11	规定病种代码	string	10	否		预留
    // //12	病种审批号	string	20	否		预留	_
    // //13	门诊序列号	string	20	是		就医地定点机构自定义的唯一就诊序列号
    // //14	疾病代码（ICD10）	string	20	是
    // //15	疾病名称	string	100	是			长度由50调整为100
    // //16	主要诊断	string	1000	否			长度由255调整为1000
    // //17	就诊时间	date	20	是		格式：yyyy-MM-dd hh24:mi:ss
    // //18	科室代码	string	10	否
    // //19	科室名称	string	50	否
    // //20	医生服务编码	string	50	否		省统一医保医师编号	长度由20调整为50
    // //21	褼AT*
    // 	string	50	否			长度由20调整为50
    // //22	操作员编号	string	20	否
    // //23	操作员姓名	string	50	否			长度由20调整为50
    // //24	医疗费用总额	double	12（2）	是		医疗费用总额=自费总额+自理总额+医保费用总额
    // //25	自费总额（非医保）	double	12（2）	是	0	指按规定不允许进入社保各项基金结算范围的全自费费用，包括丙类药品、丙类诊疗项目、丙类服务设施和超限价部分。
    // //26	自理总额（乙类目录）	double	12（2）	是	0	乙类目录个人自负部分
    // //27	医保费用总额	double	12（2）	是		进入门诊统筹可报范围费用
    // //28	费用肈AT*
    // 	integer	5	是		本次就诊药品、诊疗费用明细条数
    // //29	费用明细列表	composite				药品、费用明细列表
    // //30	附加信息	string	100	否
    // //31	对账流水号	number	30	是		与操作员管理中对账流水号相同
    // //32	终端机编号	string	12	是		读卡机具内装载的社会保障PSAM卡编号；各交易发起机构现有社会保障卡接口系统无法获取到PSAM卡编号的可以暂时传入“0”
    // //33	TAC	string	8	否		预结算时为空。	新增指标
    // //34	次要诊断列表	composite				详见下面次要诊断列表参数	新增指标
    // //-----------------------------------
    // //1	读卡类型	字符型	3	是		参考数字字典读卡类型  01	读社保卡 03	支付令牌√ 02	扫二维码
    // //2	社保卡号或二维码或支付令牌	字符型	32	是
    // //3	就诊号	字符型	20	是		就医地定点机构自定义的唯一就诊序列号
    // //4	就诊时间	字符型	20	是		格式：yyyy-MM-dd hh24:mi:ss
    // //5	科室编码	字符型	4	是		参考数字字典科室
    // //6	科室名称	字符型	100	是
    return 0 as number;
  }
